internal:
:root {
    --primary: #4f46e5;
    --success: #16a34a;
    --danger: #dc2626;
    --bg: #f8fafc;
    --card: #ffffff;
    --text: #1e293b;
}
body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: var(--bg); color: var(--text); margin: 0; padding: 20px; }
.container { max-width: 1300px; margin: 0 auto; }
.status { background: #dcfce7; color: #15803d; padding: 10px; border-radius: 6px; margin-bottom: 20px; font-weight: 600; text-align: center; }
.card { background: var(--card); border-radius: 12px; padding: 20px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1); margin-bottom: 20px; }
.flex-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }

/* Toggle Switch */
.switch-container { display: flex; align-items: center; gap: 10px; font-weight: bold; }
.switch { position: relative; display: inline-block; width: 60px; height: 34px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #ccc; transition: .4s; border-radius: 34px; }
.slider:before { position: absolute; content: ""; height: 26px; width: 26px; left: 4px; bottom: 4px; background-color: white; transition: .4s; border-radius: 50%; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(26px); }

/* Multi-line Entry Form Grid */
.voucher-header { display: grid; grid-template-columns: 200px 200px 1fr; gap: 15px; margin-bottom: 20px; background: #f1f5f9; padding: 15px; border-radius: 8px; }
.entry-row { display: grid; grid-template-columns: 120px 1fr 200px 50px; gap: 10px; margin-bottom: 10px; align-items: center; position: relative; }

label { font-size: 13px; font-weight: 600; margin-bottom: 4px; }
.form-group { display: flex; flex-direction: column; position: relative; }
input, select, textarea { padding: 8px 12px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 14px; width: 100%; box-sizing: border-box; }
textarea { resize: vertical; min-height: 60px; }

button { background: var(--primary); color: white; border: none; padding: 10px 20px; border-radius: 6px; cursor: pointer; font-weight: 600; }
button:disabled { opacity: 0.5; }
.btn-add-row { background: #0284c7; margin-bottom: 15px; padding: 6px 12px; font-size: 13px; }
.btn-remove-row { background: var(--danger); padding: 8px; font-size: 14px; height: 38px; }

/* Tables */
table { width: 100%; border-collapse: collapse; margin-top: 15px; text-align: left; }
th, td { padding: 12px; border-bottom: 1px solid #e2e8f0; font-size: 14px; vertical-align: top; }
th { background: #f1f5f9; }
.btn-sm { padding: 5px 10px; font-size: 12px; margin-right: 5px; border: none; border-radius: 4px; color: white; cursor: pointer;}
.btn-edit { background: #eab308; }
.btn-delete { background: var(--danger); }
.btn-print { background: #64748b; }
.btn-save { background: var(--success); }
.btn-cancel { background: #94a3b8; }

/* Autocomplete Suggestions */
.suggestions { position: absolute; top: 100%; left: 0; right: 0; background: white; border: 1px solid #cbd5e1; border-radius: 6px; max-height: 150px; overflow-y: auto; z-index: 99; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
.suggestion-item { padding: 8px 12px; cursor: pointer; color: #334155; }
.suggestion-item:hover { background: #f1f5f9; }

.hidden { display: none; }
.table-title { font-size: 18px; font-weight: bold; margin-top: 0; color: var(--primary); }
.badge { padding: 4px 8px; border-radius: 4px; font-size: 11px; font-weight: bold; text-transform: uppercase; }
.badge-dr { background: #dbeafe; color: #1e40af; }
.badge-cr { background: #fee2e2; color: #991b1b; }

.totals-box { text-align: right; margin-top: 10px; font-weight: bold; font-size: 15px; padding-right: 60px; }
.error-msg { color: var(--danger); font-size: 13px; font-weight: bold; margin-top: 5px; }

