window.calculateFormTotals = function() {
    let totalDr = 0, totalCr = 0;
    document.querySelectorAll(".entry-row").forEach(row => {
        const type = row.querySelector(".row-type").value;
        const amt = parseFloat(row.querySelector(".row-amount").value) || 0;
        if(type === "Dr") totalDr += amt; else totalCr += amt;
    });
    totalDrLabel.innerText = totalDr.toFixed(2);
    totalCrLabel.innerText = totalCr.toFixed(2);

    if(totalDr.toFixed(2) !== totalCr.toFixed(2)) {
        validationError.innerText = "⚠️ Total Debits must exactly equal Total Credits!";
        submitBtn.disabled = true;
    } else if(totalDr === 0) {
        validationError.innerText = "⚠️ Total Amount cannot be zero.";
        submitBtn.disabled = true;
    } else {
        validationError.innerText = "";
        submitBtn.disabled = false;
    }
};

