function generateTxnData() {
    const d = new Date();
    const currentYearShort = String(d.getFullYear()).slice(-2); 

    const timePart = String(d.getHours()).padStart(2,'0') + 
                     String(d.getMinutes()).padStart(2,'0') + 
                     String(d.getSeconds()).padStart(2,'0') + "-" + 
                     String(d.getMilliseconds()).padStart(3,'0');

    const isBasahi = tableToggle.checked;
    const prefix = isBasahi ? "B" : "N";
    const nextNum = isBasahi ? (maxBasahiVoucher + 1) : (maxNatwaVoucher + 1);

    const txnId = `TXN-${timePart}`;
    const vouchNo = `${prefix}-${currentYearShort}-${String(nextNum).padStart(4, '0')}`;

    return { txnId, vouchNo };
}

function refreshVoucherField() {
    const data = generateTxnData();
    document.getElementById("vouchNo").value = data.vouchNo;
}
setInterval(refreshVoucherField, 500);
tableToggle.addEventListener("change", refreshVoucherField);

window.removeRow = function(rowId) {
    const row = document.getElementById(rowId);
    if(row) {
        row.remove();
        window.calculateFormTotals();
    }
};

let rowCounter = 0;
function addAccountRow(type = "Dr", accountName = "", amount = "") {
    rowCounter++;
    const rowId = `entry-row-${rowCounter}`;

    const div = document.createElement("div");
    div.className = "entry-row";
    div.id = rowId;
    div.innerHTML = `
        <div>
            <select class="row-type" onchange="window.calculateFormTotals()">
                <option value="Dr" ${type === "Dr" ? "selected" : ""}>Dr</option>
                <option value="Cr" ${type === "Cr" ? "selected" : ""}>Cr</option>
            </select>
        </div>
        <div style="position:relative;">
            <input type="text" class="row-account" value="${accountName}" placeholder="Account..." autocomplete="off" required>
            <div class="suggestions hidden"></div>
        </div>
        <div>
            <input type="number" step="0.01" class="row-amount" value="${amount}" placeholder="Amount ₹" oninput="window.calculateFormTotals()" required>
        </div>
        <div>
            <button type="button" class="btn-remove-row" onclick="window.removeRow('${rowId}')">❌</button>
        </div>
    `;
    entriesContainer.appendChild(div);
    setupAccountRowSuggestions(div.querySelector(".row-account"), div.querySelector(".suggestions"));
    window.calculateFormTotals();
}

