document.getElementById("txnForm").addEventListener("submit", async (e) => {
    e.preventDefault();
    window.calculateFormTotals();
    if(submitBtn.disabled) return;

    submitBtn.disabled = true;
    const targetBranch = tableToggle.checked ? "basahi" : "natwa";
    const dbRef = ref(db, `transactions/${targetBranch}`);
    const timing = generateTxnData();

    const items = [];
    document.querySelectorAll(".entry-row").forEach(row => {
        items.push({
            type: row.querySelector(".row-type").value,
            account: row.querySelector(".row-account").value.trim(),
            amount: parseFloat(row.querySelector(".row-amount").value).toFixed(2)
        });
        uniqueAccounts.add(row.querySelector(".row-account").value.trim());
    });

    const multiLineNarration = document.getElementById("narration").value.trim();
    uniqueNarrations.add(multiLineNarration);

    try {
        await push(dbRef, {
            txn_id: timing.txnId,
            voucher_no: timing.vouchNo,
            date: document.getElementById("vouchDate").value,
            entries: items,
            narration: multiLineNarration,
            billLinks: [],
            timestamp: Date.now()
        });
        document.getElementById("speedLog").innerText = `⚡ Voucher ${timing.vouchNo} Synced Successfully!`;
        entriesContainer.innerHTML = "";
        addAccountRow("Dr"); 
        addAccountRow("Cr");
        document.getElementById("narration").value = "";
    } catch (err) { alert("Error: " + err.message); }
    submitBtn.disabled = false;
});
function parseVoucherNumber(vouchStr) {
    if(!vouchStr) return 0;
    const parts = vouchStr.split('-');
    if(parts.length >= 3) {
        return parseInt(parts[2]) || 0;
    }
    return 0;
}

// एक्टिव Firebase लिसनर्स को ट्रैक करने के लिए ग्लोबल ऑब्जेक्ट
// एक्टिव Firebase लिसनर्स को ट्रैक करने के लिए ग्लोबल ऑब्जेक्ट
let activeListeners = {};

// 1. पेज लोड होने का लॉजिक
document.addEventListener("DOMContentLoaded", () => {
    const urlParams = new URLSearchParams(window.location.search);
    let fromParam = urlParams.get('from');
    let toParam = urlParams.get('to');

    if (!fromParam || !toParam) {
        // डिफ़ॉल्ट रूप से पिछले 2 दिन
        const toDate = new Date(); 
        const fromDate = new Date();
        fromDate.setDate(toDate.getDate() - 1); 

        fromParam = fromDate.toISOString().split('T')[0];
        toParam = toDate.toISOString().split('T')[0];
    }

    document.getElementById("filterFromDate").value = fromParam;
    document.getElementById("filterToDate").value = toParam;

    // 🛠️ टॉगल स्विच का इवेंट लिसनर
    const toggleInput = document.getElementById("tableToggle");
    if (toggleInput) {
        toggleInput.addEventListener("change", () => {
            // जैसे ही टॉगल बदलेगा, यह टेबल को भी शो/हाइड करेगा और डेटा भी लोड करेगा
            applyDateFilterAndListen();
        });
    }

    // पहली बार डेटा लोड करें
    applyDateFilterAndListen();
});

// 2. फ़िल्टर और टेबल शो/हाइड करने का मुख्य फंक्शन
function applyDateFilterAndListen() {
    const fromVal = document.getElementById("filterFromDate").value;
    const toVal = document.getElementById("filterToDate").value;

    if (!fromVal || !toVal) return;

    const toggleInput = document.getElementById("tableToggle");
    if (!toggleInput) return;

    // HTML के अनुसार: Checked = Basahi (🏢), Unchecked = Natwa (🏠)
    const activeBranch = toggleInput.checked ? 'basahi' : 'natwa'; 
    const inactiveBranch = toggleInput.checked ? 'natwa' : 'basahi';

    // 🛠️ विजुअल फिक्स: एक्टिव टेबल को दिखाएं और इनएक्टिव टेबल को छुपाएं
    // (नोट: यदि आपकी पूरी <table> की ID अलग है, तो आप 'TableBody' की जगह अपनी मुख्य Table ID का उपयोग भी कर सकते हैं)
    const activeTable = document.getElementById(`${activeBranch}TableBody`);
    const inactiveTable = document.getElementById(`${inactiveBranch}TableBody`);

    // अगर आप पूरी Table को हाइड करना चाहते हैं, तो सुनिश्चित करें कि आपकी टेबल या उसके पैरेंट कंटेनर पर ये IDs हों।
    // यहाँ हम इनके बॉडी कंटेनर को मैनेज कर रहे हैं:
    if (activeTable) {
        // अगर आपने पूरे table एलिमेंट को हाइड करना है, तो .closest('table') का उपयोग करें
        const mainTable = activeTable.closest('table');
        if (mainTable) mainTable.style.display = ""; 
    }
    if (inactiveTable) {
        const mainTable = inactiveTable.closest('table');
        if (mainTable) mainTable.style.display = "none";
    }

    // A. इनएक्टिव ब्रांच का Firebase कनेक्शन तुरंत कट (Off) करें
    if (activeListeners[inactiveBranch]) {
        activeListeners[inactiveBranch](); 
        delete activeListeners[inactiveBranch];
    }

    // B. एक्टिव टेबल का पुराना डेटा साफ करें ताकि नया फ्रेश डेटा लोड हो सके
    if (activeTable) activeTable.innerHTML = ""; 

    // C. एक्टिव ब्रांच का कोई पुराना लिसनर चल रहा है, तो उसे भी बंद करें
    if (activeListeners[activeBranch]) {
        activeListeners[activeBranch]();
    }

    console.log(`Switched to: ${activeBranch}. Fetching data from ${fromVal} to ${toVal}`);

    // D. 🚀 Firebase से रेंज क्वेरी
    const branchRef = query(
        ref(db, `transactions/${activeBranch}`),
        orderByChild('date'),
        startAt(fromVal),
        endAt(toVal)
    );

        const unsubscribeAdded = onChildAdded(branchRef, (snapshot) => {
        const data = snapshot.val();
        if(!data) return;

        const vNum = parseVoucherNumber(data.voucher_no);
        if(activeBranch === 'natwa' && vNum > maxNatwaVoucher) maxNatwaVoucher = vNum;
        if(activeBranch === 'basahi' && vNum > maxBasahiVoucher) maxBasahiVoucher = vNum;

        if(data.entries) data.entries.forEach(e => uniqueAccounts.add(e.account));
        uniqueNarrations.add(data.narration);

        // 1. मुख्य डेटा रो (Transaction Row)
        const row = document.createElement("tr");
        row.id = `row-${snapshot.key}`;
        row.dataset.key = snapshot.key;
        row.dataset.branch = activeBranch;

        // 2. ठीक नीचे वाली इमेज रो (Image Row)
        const imgRow = document.createElement("tr");
        imgRow.id = `row-img-${snapshot.key}`;
        imgRow.className = "image-row";

        // दोनों रो में डेटा रेंडर करें
        renderRowStandard(row, imgRow, data);

        if(activeTable) {
            // चूँकि हम insertBefore कर रहे हैं और हम चाहते हैं कि डेटा रो ऊपर रहे और इमेज रो उसके ठीक नीचे,
            // इसलिए पहले इमेज रो इन्सर्ट होगी, फिर उसके ऊपर मुख्य डेटा रो इन्सर्ट होगी।
            activeTable.insertBefore(imgRow, activeTable.firstChild);
            activeTable.insertBefore(row, activeTable.firstChild);
        }
    });

    const unsubscribeChanged = onChildChanged(branchRef, (snapshot) => {
        const data = snapshot.val();
        if (!data) return;

        const row = document.getElementById(`row-${snapshot.key}`);
        const imgRow = document.getElementById(`row-img-${snapshot.key}`);

        if (row && imgRow) {
            renderRowStandard(row, imgRow, data);
        }
    });

    // 🔥 DELETE होने पर table से दोनों rows तुरंत हटेंगी
    const unsubscribeRemoved = onChildRemoved(branchRef, (snapshot) => {
        const row = document.getElementById(`row-${snapshot.key}`);
        const imgRow = document.getElementById(`row-img-${snapshot.key}`);

        if(row) row.remove();
        if(imgRow) imgRow.remove();

        // local cache भी हटाएँ
        delete cacheRowData[`row-${snapshot.key}`];
        delete cacheRowData[snapshot.key];
    });


activeListeners[activeBranch] = () => {
    unsubscribeAdded();
    unsubscribeChanged();
    unsubscribeRemoved();
};}

