// 4. --- आपका अपडेटेड रेंडरर फंक्शन (DD-MM-YYYY फॉर्मेट के साथ) ---// 4. --- आपका अपडेटेड रेंडरर फंक्शन (डेटा रो + इमेज रो आर्किटेक्चर) ---
function renderRowStandard(row, imgRow, data) {
    cacheRowData[row.id.replace("row-", "")] = data;
    cacheRowData[row.id] = data;

    let entriesHtml = `<div style="display:flex; flex-direction:column; gap:4px;">`;
    if(data.entries) {
        data.entries.slice().reverse().forEach(e => {
            entriesHtml += `<span><span class="badge badge-${e.type.toLowerCase()}">${e.type}</span> <b>${e.account}</b>: ₹${e.amount}</span>`;
        });
    }
    entriesHtml += `</div>`;
    const safeNarrationText = data.narration ? data.narration.replace(/\n/g, '<br>') : '';

    let docHtml = `<span class="no-doc" style="font-size:11px; color:#999;">No bills attached</span>`;

    if(data.billLinks && data.billLinks.length > 0) {
        docHtml = `
            <div class="doc-container" style="display:flex; flex-direction:row; flex-wrap:wrap; gap:8px; align-items: center;">
                <span style="font-weight: bold; font-size: 12px; color: #333;">📄 Receipts (${data.billLinks.length}): </span>
        `;

        data.billLinks.forEach((link, index) => {
            if(link.indexOf("data:image") === 0) {
                docHtml += `
                    <div class="iframe-box" style="flex: 1 1 180px; max-width: 200px; padding: 5px; background: #fff3cd; border: 1px solid #ffeba0; border-radius: 4px;">
                        <span class="badge-process" style="background:#ffc107; color:#000; padding:2px 5px; font-size:10px; font-weight:bold; border-radius:3px;">⚡ Uploading</span><br>
                        <img src="${link}" style="width:100%; max-height:120px; object-fit:contain; border-radius:4px; margin-top:5px;">
                    </div>`;
            } else {
                docHtml += `
                    <div class="iframe-box" style="flex: 1 1 180px; max-width: 200px; padding: 5px; background: #d4edda; border: 1px solid #c3e6cb; border-radius: 4px;">
                        <span class="badge-drive" style="background:#28a745; color:#fff; padding:2px 5px; font-size:10px; font-weight:bold; border-radius:3px;">☁ Cloud Link</span><br>
                        <iframe src="${link}" width="100%" height="120" style="border:none; margin-top:5px; border-radius:4px; background:#fff;"></iframe>
                    </div>`;
            }
        });

        docHtml += `</div>`;
    }

    // तारीख को YYYY-MM-DD से बदलकर DD-MM-YYYY फॉर्मेट में स्क्रीन पर दिखाने का लॉजिक
    let displayDate = "";
    if (data.date && data.date.includes("-")) {
        const parts = data.date.split("-");
        displayDate = `${parts[2]}-${parts[1]}-${parts[0]}`; 
    } else {
        displayDate = data.date || "";
    }

    // 1. मुख्य रो में केवल ट्रांजैक्शन की डिटेल्स रहेंगी (रिसीप्ट हटा दी गई है)
    row.innerHTML = `
        <td><small><b>${data.txn_id}</b></small></td>
        <td><b>${data.voucher_no}</b></td>
        <td>${displayDate}</td>
        <td>${entriesHtml}</td>
        <td><span style="white-space: pre-line;">${safeNarrationText}</span></td>
        <td>
            <button class="btn-sm btn-edit" onclick="triggerInlineEdit('${row.id}')">Edit</button>
            <button class="btn-sm btn-delete" onclick="triggerDelete('${row.id}')">Delete</button>
            <button class="btn-sm btn-print" onclick="triggerPrint('${row.id}')">Print</button>
        </td>
