// इनलाइन एडिट के लिए सुरक्षित कंप्रेशन इंजन (इसे अपने स्क्रिप्ट में नीचे जोड़ दें)
function convertInlineFileToBase64(file) {
    return new Promise(async (resolve, reject) => {
        if (file.type.startsWith('image/')) {
            const options = {
                maxSizeMB: 2.5,          // 🌟 Quality badhane ke liye size limit ko 2.5 MB kiya (ताकि डिटेल्स मिस न हों)
                maxWidthOrHeight: 1600,  // 🌟 Dimensions ko 1600 kiya (ताकि टेक्स्ट और इमेज बिल्कुल साफ और HD दिखें)
                useWebWorker: true,
                initialQuality: 0.95     // 🌟 Compression quality ko 95% par set kiya (ताकि original quality barkarar rahe)
            };
            try {
                const compressedBlob = await imageCompression(file, options);
                const reader = new FileReader();
                reader.readAsDataURL(compressedBlob);
                reader.onloadend = () => resolve(reader.result);
            } catch (err) {
                reject(err);
            }
        } else {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onloadend = () => resolve(reader.result);
        }
    });
}

